function loneValue(nums: number[]): number {
  const count = new Map<number, number>();
  for (const v of nums) count.set(v, (count.get(v) ?? 0) + 1);
  for (const [v, c] of count) if (c === 1) return v;
  return 0; // unreachable: a lone value is guaranteed
}

